<script setup>
import { Head, useForm } from '@inertiajs/vue3';
const props = defineProps({ token: String, email: String }); const form = useForm({ token: props.token, email: props.email, password: '', password_confirmation: '' });
</script>
<template><Head title="Nouveau mot de passe" /><main class="grid min-h-screen place-items-center bg-[#fbfaf6] p-6"><div class="w-full max-w-md rounded-3xl bg-white p-8 shadow-sm"><a href="/" class="font-serif text-2xl font-semibold">tempo<span class="text-coral">.</span></a><p class="mt-10 text-xs font-bold uppercase tracking-[.2em] text-coral">Sécurité</p><h1 class="mt-2 font-serif text-4xl">Nouveau mot de passe</h1><form @submit.prevent="form.post('/reinitialiser-mot-de-passe')" class="mt-7 space-y-4"><label class="block text-sm font-semibold">Adresse e-mail<input v-model="form.email" type="email" autocomplete="email" class="mt-2 w-full rounded-2xl border border-black/10 px-4 py-3.5 font-normal" /></label><label class="block text-sm font-semibold">Nouveau mot de passe<input v-model="form.password" type="password" autocomplete="new-password" class="mt-2 w-full rounded-2xl border border-black/10 px-4 py-3.5 font-normal" /></label><label class="block text-sm font-semibold">Confirmer le mot de passe<input v-model="form.password_confirmation" type="password" autocomplete="new-password" class="mt-2 w-full rounded-2xl border border-black/10 px-4 py-3.5 font-normal" /></label><p v-if="Object.keys(form.errors).length" class="rounded-xl bg-red-50 p-3 text-sm text-red-600">{{ Object.values(form.errors)[0] }}</p><button :disabled="form.processing" class="w-full rounded-full bg-ink py-4 font-bold text-white hover:bg-coral disabled:opacity-50">Enregistrer le mot de passe</button></form></div></main></template>
